mapper.select:
SELECT substring(주문일자 from 1 for 7) as orderDate ,count(*) as orderCount ,coalesce(sum(결재금액), 0) as totalAmount ,sum(인쇄횟수) as totalPrintCount from (select A.* , (case when 인쇄도수 = '1도인쇄' then 1 when 인쇄도수 = '2도인쇄' then 2 when 인쇄도수 = '3도인쇄' then 3 when 인쇄도수 = '4도인쇄' then 4 when 인쇄도수 = 'CMYK인쇄' then 1 else 0 end) * (case when 인쇄면 = '단면' then 1 when 인쇄면 = '양면' then 2 else 0 end) * (case when isnumber(replace(제작장수,',','')) then cast(replace(제작장수,',','') as integer) else 0 end) * (case when 인쇄방법 in ('실크인쇄', '간편인쇄') then 1 else null end) as 인쇄횟수 from public.인쇄정보 A) where 주문일자 between #{startDate}||'01' and #{endDate}||'31'
and coalesce(배분여부, 'false') = #{distributeYn}
and coalesce(기존주문여부, '신규주문') = #{existOrderYn}
group by substring(주문일자 from 1 for 7) order by substring(주문일자 from 1 for 7) asc

select case when teamName is null or trim(teamName) = '' then '미배정' else teamName end as teamName ,sum(orderCount) as orderCount ,sum(totalAmount) as totalAmount ,sum(totalPrintCount) as totalPrintCount from ( SELECT coalesce(인쇄담당팀, '미배정') as teamName ,count(*) as orderCount ,coalesce(sum(결재금액), 0) as totalAmount ,sum(인쇄횟수) as totalPrintCount from (select A.* , (case when 인쇄도수 = '1도인쇄' then 1 when 인쇄도수 = '2도인쇄' then 2 when 인쇄도수 = '3도인쇄' then 3 when 인쇄도수 = '4도인쇄' then 4 when 인쇄도수 = 'CMYK인쇄' then 1 else 0 end) * (case when 인쇄면 = '단면' then 1 when 인쇄면 = '양면' then 2 else 0 end) * (case when isnumber(replace(제작장수,',','')) then cast(replace(제작장수,',','') as integer) else 0 end) * (case when 인쇄방법 in ('실크인쇄', '간편인쇄') then 1 else null end) as 인쇄횟수 from public.인쇄정보 A) where 주문일자 like #{startDate} || '%'
and coalesce(배분여부, 'false') = #{distributeYn}
and coalesce(기존주문여부, '신규주문') = #{existOrderYn}
group by 인쇄담당팀 ) group by teamName order by teamName

select case when 인쇄방법 is null or trim(인쇄방법) = '' then '미지정' else 인쇄방법 end as methodName, count(*) as orderCount, coalesce(sum(결재금액), 0) as totalAmount, coalesce(sum( (case when 인쇄도수 = '1도인쇄' then 1 when 인쇄도수 = '2도인쇄' then 2 when 인쇄도수 = '3도인쇄' then 3 when 인쇄도수 = '4도인쇄' then 4 when 인쇄도수 = 'CMYK인쇄' then 1 else 0 end) * (case when 인쇄면 = '단면' then 1 when 인쇄면 = '양면' then 2 else 0 end) * (case when isnumber(replace(제작장수, ',', '')) then cast(replace(제작장수, ',', '') as integer) else 0 end) * (case when 인쇄방법 in ('실크인쇄', '간편인쇄') then 1 else 0 end) ), 0) as totalPrintCount from public.인쇄정보 where 주문일자 like #{startDate} || '%'
and coalesce(배분여부, 'false') = #{distributeYn}
and coalesce(기존주문여부, '신규주문') = #{existOrderYn}
group by case when 인쇄방법 is null or trim(인쇄방법) = '' then '미지정' else 인쇄방법 end order by methodName

choose.when:
select stateName as stateName,
       stateCount as stateCount
  from (
        select '피킹' as stateName,
               sum(case when coalesce(피킹완료, '') in ('Y', 'YES', 'true', '1', '완료', '완료됨') then 1 else 0 end) as stateCount
          from public.인쇄정보
         where 주문일자 like #{startDate} || '%'

           and coalesce(배분여부, 'false') = #{distributeYn}


           and coalesce(기존주문여부, '신규주문') = #{existOrderYn}

        union all
        select '인쇄' as stateName,
               sum(case when coalesce(인쇄완료, '') in ('Y', 'YES', 'true', '1', '완료', '완료됨') then 1 else 0 end) as stateCount
          from public.인쇄정보
         where 주문일자 like #{startDate} || '%'

           and coalesce(배분여부, 'false') = #{distributeYn}


           and coalesce(기존주문여부, '신규주문') = #{existOrderYn}

        union all
        select '배분' as stateName,
               sum(case when coalesce(배분여부, '') in ('Y', 'YES', 'true', '1', '완료', '배분', '배분완료') then 1 else 0 end) as stateCount
          from public.인쇄정보
         where 주문일자 like #{startDate} || '%'

           and coalesce(배분여부, 'false') = #{distributeYn}


           and coalesce(기존주문여부, '신규주문') = #{existOrderYn}

        union all
        select '완료' as stateName,
               sum(case when coalesce(완료여부, '') in ('Y', 'YES', 'true', '1', '완료', '완료됨') then 1 else 0 end) as stateCount
          from public.인쇄정보
         where 주문일자 like #{startDate} || '%'

           and coalesce(배분여부, 'false') = #{distributeYn}


           and coalesce(기존주문여부, '신규주문') = #{existOrderYn}

       ) d
 order by stateName

choose.otherwise:
select stateName as stateName, count(*) as stateCount from ( select case #{stateType} when 'pickingYn' then case when coalesce(피킹완료, '') in ('Y', 'YES', 'true', '1', '완료', '완료됨') then '피킹' when coalesce(피킹완료, '') in ('N', 'NO', 'false', '0', '미완료', '미완료됨', '') then '미피킹' else coalesce(cast(피킹완료 as varchar), '미확인') end when 'printYn' then case when coalesce(인쇄완료, '') in ('Y', 'YES', 'true', '1', '완료', '완료됨') then '인쇄' when coalesce(인쇄완료, '') in ('N', 'NO', 'false', '0', '미완료', '미완료됨', '') then '미인쇄' else coalesce(cast(인쇄완료 as varchar), '미확인') end when 'distributeYn' then case when coalesce(배분여부, '') in ('Y', 'YES', 'true', '1', '완료', '배분', '배분완료') then '배분' when coalesce(배분여부, '') in ('N', 'NO', 'false', '0', '미완료', '미배분', '미배분완료', '') then '미배분' else coalesce(cast(배분여부 as varchar), '미확인') end when 'completeYn' then case when coalesce(완료여부, '') in ('Y', 'YES', 'true', '1', '완료', '완료됨') then '완료' when coalesce(완료여부, '') in ('N', 'NO', 'false', '0', '미완료', '미완료됨', '') then '미완료' else coalesce(cast(완료여부 as varchar), '미확인') end else '미확인' end as stateName from public.인쇄정보 where 주문일자 like #{startDate} || '%'
and coalesce(배분여부, 'false') = #{distributeYn}
and coalesce(기존주문여부, '신규주문') = #{existOrderYn}
) x where stateName is not null group by stateName order by stateName
